import axios from "axios";
import { useState, useRef } from "react";
import Result from "./Result";
import "../App.css";

function ResumeUpload({ jobId }) {
  const [result, setResult] = useState(null);
  const [dragOver, setDragOver] = useState(false);
  const [fileName, setFileName] = useState("");
  const [progress, setProgress] = useState(0);
  const [errorMsg, setErrorMsg] = useState(null);
  const inputRef = useRef(null);

  const uploadFile = async (file) => {
    if (!file) return;
    setFileName(file.name);
    const formData = new FormData();
    formData.append("resume", file);
    if (jobId) formData.append("jobId", jobId);
    try {
      setErrorMsg(null);
      const res = await axios.post(
        "/api/resume/upload",
        formData,
        {
          headers: { "Content-Type": "multipart/form-data" },
          withCredentials: true,
          onUploadProgress: (progressEvent) => {
            const percent = Math.round(
              (progressEvent.loaded * 100) / progressEvent.total
            );
            setProgress(percent);
          },
          timeout: 60000
        }
      );
      setResult(res.data.data);
    } catch (err) {
      console.error('Upload error:', err);
      const msg = err?.response?.data?.error || err?.message || 'Upload failed';
      setErrorMsg(msg);
    } finally {
      setProgress(0);
    }
  };

  const handleFiles = (files) => {
    const file = files && files[0];
    uploadFile(file);
  };

  const onDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    handleFiles(e.dataTransfer.files);
  };

  const onDragOver = (e) => {
    e.preventDefault();
    setDragOver(true);
  };

  const onDragLeave = () => setDragOver(false);

  return (
    <div className="upload-section">
      <div
        className={`drop-zone ${dragOver ? "drag-over" : ""}`}
        onDrop={onDrop}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onClick={() => inputRef.current && inputRef.current.click()}
        style={{
          minHeight: '240px',
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'center',
          background: dragOver ? 'var(--accent-light)' : '#fff',
          border: dragOver ? '2px dashed var(--accent)' : '2px dashed #cbd5e1',
          borderRadius: '16px',
          transition: 'all 0.3s ease'
        }}
      >
        <div className="mb-4 text-accent">
          <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
            <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
            <polyline points="17 8 12 3 7 8" />
            <line x1="12" y1="3" x2="12" y2="15" />
          </svg>
        </div>
        <p className="font-bold text-slate-700 mb-1">Push to AI Analysis</p>
        <p className="muted text-xs">Drag and drop your file here, or click to select</p>
        <input
          ref={inputRef}
          type="file"
          accept=".pdf,.doc,.docx"
          style={{ display: "none" }}
          onChange={(e) => handleFiles(e.target.files)}
        />
      </div>

      {fileName && (
        <div className="upload-preview mt-6">
          <div className="flex items-center gap-2 mb-2">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M13 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9z"></path><polyline points="13 2 13 9 20 9"></polyline></svg>
            <span className="file-name">{fileName}</span>
          </div>
          {progress > 0 && (
            <div className="progress-bar">
              <div
                className="progress"
                style={{ width: `${progress}%` }}
                aria-valuenow={progress}
              />
            </div>
          )}

          {errorMsg && <div className="alert alert-danger mt-2">{errorMsg}</div>}
        </div>
      )}

      {result && (
        <div className="mt-8">
          <Result data={result} />
        </div>
      )}
    </div>
  );
}

export default ResumeUpload;
